page('event-pass/index.html','3D Event Planner | $9.99 One-Time Event Pass | RentSketch','Plan one event in 2D and 3D for $9.99 once. Get 30 days to edit, save, print and share your layout. No subscription or automatic renewal.', f'''<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">For weddings, parties and tent events</div><h1>Plan one event.<br><span>See it before setup day.</span></h1><p class="lead">Arrange tents, tables, chairs, dance floors and more in 2D and 3D. Your Event Pass gives you 30 days to edit, save, print and share one event.</p><div class="actions"><a class="btn primary" href="{event_pass_url('rentsketch_event_pass_page_hero')}">Start my event · $9.99 ↗</a><a class="btn" href="/demo/">Watch the free demo</a></div><div class="inline-proof"><span>$9.99 once</span><span>30 days</span><span>No subscription</span></div><p class="micro">Stripe hosts payment. Rental equipment, delivery and venue costs are separate.</p></div>'''+studio()+f'''</div></section><section class="section"><div class="wrap"><div class="section-heading center"><div class="eyebrow">What the Event Pass includes</div><h2>One layout you can keep working on.</h2></div><div class="steps"><article class="step"><span class="number">01</span><h3>Build the layout.</h3><p>Start with the space or tent. Add tables, chairs, a dance floor and other supported event equipment.</p></article><article class="step"><span class="number">02</span><h3>Switch between 2D + 3D.</h3><p>Use the floor plan for placement and the 3D view to help picture the same event.</p></article><article class="step"><span class="number">03</span><h3>Save, print and share.</h3><p>Return through your private access link during the 30-day term and keep refining the same event.</p></article></div></div></section><section class="section tinted"><div class="wrap two-col"><div><div class="eyebrow">Simple pricing</div><h2>$9.99 once.<br>No recurring plan.</h2><p>The Event Pass is software access for one event for 30 days. If you need more time, you can optionally renew the same event for $4.99 for another 30 days.</p><p>No subscription. No automatic renewal. Completing a layout does not reserve rental equipment.</p></div><div class="event-pass"><div><span class="pill">One Event Pass</span><h3 style="margin-top:13px">$9.99 · 30 days</h3><p>Edit · save · print · share · 2D + 3D</p></div><a class="btn primary" href="{event_pass_url('rentsketch_event_pass_page_pricing')}">Start planning · $9.99 ↗</a></div></div></section><section class="section"><div class="wrap faq-layout"><div><h2>Before you pay.</h2><p>Know exactly what the pass does.</p></div>'''+faq([('Does $9.99 include rental equipment?','No. The Event Pass pays only for RentSketch software access. Tents, tables, chairs, delivery, installation and venue costs are separate.'),('Is this a subscription?','No. The $9.99 Event Pass is a one-time payment for 30 days of access to one event. It does not renew automatically.'),('Can I see it before paying?','Yes. Use the free demo to see how 2D and 3D layouts work. The Event Pass is for creating and keeping your own event.'),('What happens after I pay?','Stripe verifies the payment, RentSketch opens your saved event, and an access email is sent with a private link so you can return during the access period.'),('Can I use it for a wedding?','Yes. It is intended for a single event such as a wedding reception, party, tent event or similar layout-planning project.')])+'''</div></section>'''+event_cta('rentsketch_event_pass_page_footer'),tour=True)

page('help/index.html','Getting Started & Purchase Help | RentSketch','Set up your rental business workspace, understand the trial, manage subscriptions and recover a purchased Event Pass. RentSketch customer help.', '''<section class="page-hero"><div class="wrap"><div class="eyebrow">RentSketch help</div><h1>Your next step,<br>made clear.</h1><p>Set up your workspace or get back to the event you purchased.</p></div></section><section class="section"><div class="wrap guide"><article><h2 id="business">Set up a business workspace</h2><ol><li><a href="/business/signup.html">Create a 14-day trial</a>. No credit card is required.</li><li>Open <strong>Products</strong> and add the equipment you want customers to use. Set names, dimensions, prices and supported visual models.</li><li>Open <strong>Branding</strong> and configure your business identity.</li><li>Open <strong>Install</strong>, preview your designer, and add your website’s domain before embedding.</li><li>Review your own customer journey before publishing. Submitted quote requests appear in <strong>Requests</strong>.</li></ol><h2>Choose a paid business subscription</h2><p>In your dashboard, open Billing, choose a plan and select monthly or yearly billing. Stripe Checkout displays the payment details before you subscribe. Your trial does not charge you automatically.</p><p>If you already have a subscription, use Manage Billing in Stripe to manage it. Returning from Checkout alone does not confirm payment; the dashboard reads the saved subscription status.</p><h2>Purchase an individual Event Pass</h2><p>Watch the free demo if you want to see the workflow first. When you are ready to design your own event, choose the $9.99 Event Pass and continue to Stripe. Stripe collects the purchaser email; verified payment activates 30 days of editing for one event.</p><p>After verified payment, you return to the event and receive a private access link by email. Keep the link private. Equipment rentals are a separate purchase.</p><h2>Find an event you already paid for</h2><p>Use your purchase email’s private link, or visit <a href="/my-event/">Open my saved event</a> and request the access email again. Check the spelling of the email address and your spam folder. A pending payment or a canceled checkout does not activate a pass.</p><h2>Get help with a purchase</h2><p>Email <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with the account email, approximate purchase date and what went wrong. Do not send passwords or full card details.</p></article><aside class="guide-aside"><h3>Quick links</h3><a href="/dashboard/">Business dashboard →</a><a href="/my-event/">Open my saved event →</a><a href="/business/pricing.html">Pricing →</a><a href="/demo/">Explore the demo →</a></aside></div></section>''')

page('privacy/index.html','RentSketch Privacy Notice | Data, Analytics & Event Designs','Learn how RentSketch uses account information, event designs and payment references to operate its event planning software.', '''<section class="page-hero"><div class="wrap"><h1>Privacy at RentSketch.</h1><p>Information used to provide the event design service.</p></div></section><section class="section"><div class="wrap guide"><article><h2>Account and event information</h2><p>RentSketch stores business account information, including the business name, email address and a hashed password. The service also stores event designs and the information submitted with quote requests so users and the relevant rental business can work with those plans.</p><h2>Payments and access</h2><p>Stripe hosts checkout and handles payment information. RentSketch stores payment references, payment status, the purchase email and access periods to provide subscriptions or Event Pass access. Private event links are used to reopen a purchased design.</p><h2>Browser storage</h2><p>The designer uses browser storage for draft and session information. The business dashboard stores a sign-in token so the account can remain signed in. Signing out clears the dashboard token; clearing browser storage can remove local drafts and preview state.</p><h2>Analytics and performance</h2><p>RentSketch uses Google Analytics to understand site usage and conversions. Google may process browser, device and network information under its own terms. RentSketch also records first-party Web Vitals such as Largest Contentful Paint (LCP), Cumulative Layout Shift (CLS), Interaction to Next Paint (INP), First Contentful Paint (FCP) and Time to First Byte (TTFB), together with the page path, broad device class and navigation type. These performance records do not store names, email addresses, IP addresses, event designs or payment card data.</p><h2>Service providers and rental businesses</h2><p>Hosting, analytics, payment and email services process information needed to operate and improve RentSketch. When you use a rental company’s designer and submit an event or quote request, that business receives the relevant information. Its handling of rental orders is separate from RentSketch software access.</p><h2>Questions and requests</h2><p>Contact <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with privacy, account or data requests. Include enough information to identify your account, but never send a password, full payment card number or private event access link.</p></article></div></section>''')

page('404.html','Page Not Found | RentSketch','Find your way back to RentSketch event design software.', '''<div class="error-panel"><div class="eyebrow">404 · Page not found</div><h1>Let’s get you back<br>to the plan.</h1><p>This address does not match a RentSketch page.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="/">Go to RentSketch</a><a class="btn" href="/my-event/">Open my saved event</a></div></div>''',noindex=True)

